// L7 self-protection DEV set (plan 02 §2.2 and 04 §L7), written from the plan only by
// the implementer, apart from the held-out guards corpus (D29: that corpus is scored on
// totals and never read item by item). Tune against this file, never against the corpus.
//
// Placeholders as in the corpus: {pkg} (the product's command), {adroot} (spelled per tool
// and OS by testkit/rule-examples.mjs substitute), plus {home} (the absolute home folder
// for file tools). Every item is a Claude Code call unless host says codex.
//   expect: "deny" | "ask" | "allow"   (ask = Claude Code default mode; Codex turns it into deny)
//   cls: a verbs, b wrappers, c state, d host config, e env, f Windows folder, g run-time built

const L = (id, cls, expect, command, extra = {}) => ({ id, cls, expect, host: "claude-code", tool: "Bash", os: "linux", cwd: "/work/app", project_root: "/work/app", input: { command }, ...extra });
const P = (id, cls, expect, command, extra = {}) => L(id, cls, expect, command, { tool: "PowerShell", os: "windows", cwd: String.raw`C:\work\app`, project_root: String.raw`C:\work\app`, ...extra });
const F = (id, cls, expect, tool, input, extra = {}) => ({ id, cls, expect, host: "claude-code", tool, os: "linux", cwd: "/work/app", project_root: "/work/app", input, ...extra });
const patch = (body) => `apply_patch <<'EOF'\n*** Begin Patch\n${body}\n*** End Patch\nEOF\n`;

